import { useRef, useState } from 'react';
import { Calendar, type CalendarSingleProps } from '../calendar/Calendar';
import { formatDate, toISODate } from '../calendar/calendar-utils';
import { Popover, PopoverContent } from '../popover';
import { DateTrigger } from './DateTrigger';
import { useI18n, useOptionalI18n } from '../../i18n/I18nProvider';
import type { DatePickerVariantProps } from './date-picker.variants';

type CalendarPassThrough = Pick<CalendarSingleProps, 'locale' | 'weekStartsOn' | 'min' | 'max' | 'isDateDisabled' | 'today'>;

export interface DatePickerProps extends CalendarPassThrough, DatePickerVariantProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (date: Date | null) => void;
  /** Intl options for the field text. */
  formatOptions?: Intl.DateTimeFormatOptions;
  placeholder?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Submitted as `YYYY-MM-DD` through a hidden input. */
  name?: string;
  id?: string;
  disabled?: boolean;
  invalid?: boolean;
  className?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
}

/** Initial focus inside the popup: the calendar's tabbable day. */
export function focusCalendarDay(container: HTMLElement | null) {
  return container?.querySelector<HTMLElement>('button[data-day][tabindex="0"]') ?? true;
}

/**
 * Date field: a read-only input with the formatted date that opens a Popover with a Calendar.
 * Enter/Space/click open it, focus lands on the selected day, picking a day (or Escape)
 * closes it and focus returns to the field.
 */
export function DatePicker({
  value,
  defaultValue,
  onValueChange,
  formatOptions,
  placeholder: placeholderProp,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  name,
  id,
  disabled,
  invalid,
  size,
  className,
  locale: localeProp,
  weekStartsOn,
  min,
  max,
  isDateDisabled,
  today,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
}: DatePickerProps) {
  const { t } = useI18n();
  const providerLocale = useOptionalI18n()?.locale;
  const locale = localeProp ?? providerLocale;
  const placeholder = placeholderProp ?? t('datePicker.placeholder');
  const [inner, setInner] = useState<Date | null>(defaultValue ?? null);
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const calendarRef = useRef<HTMLDivElement | null>(null);
  const date = value !== undefined ? value : inner;
  const open = openProp ?? innerOpen;

  const setOpen = (next: boolean) => {
    setInnerOpen(next);
    onOpenChange?.(next);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <DateTrigger
        text={date ? formatDate(date, locale, formatOptions) : ''}
        placeholder={placeholder}
        id={id}
        disabled={disabled}
        invalid={invalid}
        size={size}
        className={className}
        aria-label={ariaLabel}
        aria-describedby={ariaDescribedBy}
      />
      {name && <input type="hidden" name={name} value={date ? toISODate(date) : ''} />}
      <PopoverContent aria-label={t('datePicker.choose')} align="start" sideOffset={6} padding="none" initialFocus={() => focusCalendarDay(calendarRef.current)}>
        <Calendar
          ref={calendarRef}
          aria-label={t('datePicker.choose')}
          value={date}
          onValueChange={(d) => {
            setInner(d);
            onValueChange?.(d);
            setOpen(false);
          }}
          locale={locale}
          weekStartsOn={weekStartsOn}
          min={min}
          max={max}
          isDateDisabled={isDateDisabled}
          today={today}
        />
      </PopoverContent>
    </Popover>
  );
}

import { useRef, useState } from 'react';
import { cn } from '../../utils/cn';
import { Calendar, type CalendarRangeProps } from '../calendar/Calendar';
import { formatDateRange, startOfDay, toISODate, type DateRange } from '../calendar/calendar-utils';
import { Popover, PopoverContent } from '../popover';
import { focusCalendarDay } from './DatePicker';
import { DateTrigger } from './DateTrigger';
import { DEFAULT_DATE_RANGE_PRESETS, matchPreset, type DateRangePreset } from './date-range-presets';
import { useI18n, useOptionalI18n } from '../../i18n/I18nProvider';
import { datePickerVariants, type DatePickerVariantProps } from './date-picker.variants';

type CalendarPassThrough = Pick<CalendarRangeProps, 'locale' | 'weekStartsOn' | 'min' | 'max' | 'isDateDisabled' | 'numberOfMonths'>;

export interface DateRangePickerProps extends CalendarPassThrough, DatePickerVariantProps {
  value?: DateRange;
  defaultValue?: DateRange;
  /** Fires with complete ranges only (both ends set). */
  onValueChange?: (range: DateRange) => void;
  /** Quick ranges shown beside the calendar; pass `[]` to hide them. */
  presets?: DateRangePreset[];
  /** "Today" for the presets and the marker. Defaults to the current date. */
  today?: Date;
  formatOptions?: Intl.DateTimeFormatOptions;
  placeholder?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Submitted as `<name>-start` / `<name>-end` (`YYYY-MM-DD`). */
  name?: string;
  id?: string;
  disabled?: boolean;
  invalid?: boolean;
  className?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
}

const EMPTY: DateRange = { start: null, end: null };

/**
 * Date range field: the formatted range in a read-only input that opens presets (Today,
 * Last 7 days, Last 30 days, This month, Last month, Custom) next to a two-month range
 * Calendar. A preset or the second calendar click applies the range and closes the popup.
 */
export function DateRangePicker({
  value,
  defaultValue,
  onValueChange,
  presets = DEFAULT_DATE_RANGE_PRESETS,
  today: todayProp,
  formatOptions,
  placeholder: placeholderProp,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  name,
  id,
  disabled,
  invalid,
  size,
  className,
  locale: localeProp,
  weekStartsOn,
  min,
  max,
  isDateDisabled,
  numberOfMonths = 2,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
}: DateRangePickerProps) {
  const { t } = useI18n();
  const providerLocale = useOptionalI18n()?.locale;
  const locale = localeProp ?? providerLocale;
  const placeholder = placeholderProp ?? t('datePicker.rangePlaceholder');
  const [inner, setInner] = useState<DateRange>(defaultValue ?? EMPTY);
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const [draft, setDraft] = useState<DateRange>(value ?? inner);
  const [customActive, setCustomActive] = useState(false);
  const [now] = useState(() => startOfDay(new Date()));
  const today = todayProp ? startOfDay(todayProp) : now;
  const calendarRef = useRef<HTMLDivElement | null>(null);
  const range = value ?? inner;
  const open = openProp ?? innerOpen;
  const s = datePickerVariants({ size });
  const active = customActive ? presets.find((p) => !p.range) : (matchPreset(presets, draft, today) ?? (draft.start ? presets.find((p) => !p.range) : undefined));

  const setOpen = (next: boolean) => {
    if (next) {
      setDraft(range);
      setCustomActive(false);
    }
    setInnerOpen(next);
    onOpenChange?.(next);
  };

  const apply = (next: DateRange) => {
    setInner(next);
    onValueChange?.(next);
    setOpen(false);
  };

  const pickPreset = (p: DateRangePreset) => {
    if (p.range) {
      apply(p.range(today));
      return;
    }
    setCustomActive(true);
    const day = focusCalendarDay(calendarRef.current);
    if (day !== true) day.focus();
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <DateTrigger
        text={formatDateRange(range, locale, formatOptions)}
        placeholder={placeholder}
        id={id}
        disabled={disabled}
        invalid={invalid}
        size={size}
        className={className}
        aria-label={ariaLabel}
        aria-describedby={ariaDescribedBy}
      />
      {name && (
        <>
          <input type="hidden" name={`${name}-start`} value={range.start ? toISODate(range.start) : ''} />
          <input type="hidden" name={`${name}-end`} value={range.end ? toISODate(range.end) : ''} />
        </>
      )}
      <PopoverContent aria-label={t('datePicker.chooseRange')} align="start" sideOffset={6} padding="none" initialFocus={() => focusCalendarDay(calendarRef.current)}>
        <div className={s.panel()}>
          {presets.length > 0 && (
            <div role="group" aria-label={t('datePicker.presets')} className={s.presets()}>
              {presets.map((p) => (
                <button key={p.id} type="button" aria-pressed={active?.id === p.id} className={cn(s.preset())} onClick={() => pickPreset(p)}>
                  {p.label}
                </button>
              ))}
            </div>
          )}
          <Calendar
            ref={calendarRef}
            mode="range"
            aria-label={t('datePicker.chooseRange')}
            value={draft}
            onValueChange={(r) => {
              setDraft(r);
              setCustomActive(true);
              if (r.start && r.end) apply(r);
            }}
            numberOfMonths={numberOfMonths}
            defaultMonth={draft.end && numberOfMonths === 2 ? new Date(draft.end.getFullYear(), draft.end.getMonth() - 1, 1) : undefined}
            locale={locale}
            weekStartsOn={weekStartsOn}
            min={min}
            max={max}
            isDateDisabled={isDateDisabled}
            today={today}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

/** Alias: the range field is also catalogued as DateRangeInput. */
export const DateRangeInput = DateRangePicker;
export type DateRangeInputProps = DateRangePickerProps;

import { Field } from '@base-ui/react/field';
import { mergeProps } from '@base-ui/react/merge-props';
import { CalendarDays, ChevronDown } from 'lucide-react';
import type { ComponentProps, Ref } from 'react';
import { cn } from '../../utils/cn';
import { PopoverTrigger } from '../popover';
import { datePickerVariants, type DatePickerVariantProps } from './date-picker.variants';

export interface DateTriggerProps extends DatePickerVariantProps {
  text: string;
  placeholder: string;
  id?: string;
  disabled?: boolean;
  invalid?: boolean;
  className?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
}

/**
 * Read-only input that opens the popover (combobox with a dialog popup). It is both the
 * Popover trigger and a Base UI Field control, so FieldLabel / FieldDescription wire to it.
 */
export function DateTrigger({ text, placeholder, id, disabled, invalid, size = 'md', className, ...aria }: DateTriggerProps) {
  const s = datePickerVariants({ size });
  const px = size === 'sm' ? 14 : 15;
  return (
    <div className={cn(s.root(), className)}>
      <CalendarDays size={px} aria-hidden className={s.icon()} />
      <PopoverTrigger
        nativeButton={false}
        disabled={disabled}
        render={(triggerProps) => {
          const { ref, ...rest } = triggerProps as ComponentProps<'input'>;
          return (
            <Field.Control
              ref={ref as Ref<HTMLInputElement>}
              id={id}
              disabled={disabled}
              render={(controlProps) => (
                <input
                  {...mergeProps<'input'>(controlProps as ComponentProps<'input'>, rest, {
                    role: 'combobox',
                    readOnly: true,
                    value: text,
                    placeholder,
                    autoComplete: 'off',
                    'aria-invalid': invalid || undefined,
                    ...(aria['aria-label'] ? { 'aria-label': aria['aria-label'] } : {}),
                    ...(aria['aria-describedby'] ? { 'aria-describedby': aria['aria-describedby'] } : {}),
                    className: s.input(),
                  })}
                />
              )}
            />
          );
        }}
      />
      <ChevronDown size={px} aria-hidden className={s.chevron()} />
    </div>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

/**
 * The trigger is a read-only input styled as the brand field (calendar icon and chevron are
 * overlays inside its padding), so the whole field is the popover anchor.
 */
export const datePickerVariants = tv({
  slots: {
    root: 'relative flex w-full min-w-0 items-center',
    input: [
      'w-full min-w-0 cursor-pointer truncate rounded-md border border-border bg-background text-start text-foreground caret-transparent shadow-sm outline-none',
      'transition-colors motion-reduce:transition-none placeholder:text-muted-foreground hover:border-muted-foreground/40',
      'focus-visible:border-primary/60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      'data-popup-open:border-primary/60 data-invalid:border-destructive/70 aria-invalid:border-destructive/70',
      'disabled:cursor-not-allowed disabled:bg-secondary/50 disabled:text-muted-foreground disabled:hover:border-border',
    ],
    icon: 'pointer-events-none absolute shrink-0 text-muted-foreground',
    chevron: 'pointer-events-none absolute shrink-0 text-muted-foreground',
    panel: 'flex flex-col sm:flex-row',
    presets: 'flex shrink-0 flex-row flex-wrap gap-1 border-b border-border p-2 sm:w-36 sm:flex-col sm:flex-nowrap sm:border-e sm:border-b-0',
    preset: [
      'rounded-[6px] px-2.5 py-1.5 text-start text-[12.5px] text-foreground transition-colors motion-reduce:transition-none',
      'hover:bg-secondary/70 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-focus-ring',
      'aria-pressed:bg-primary/12 aria-pressed:font-medium aria-pressed:text-primary-chip-text',
    ],
  },
  variants: {
    size: {
      sm: { input: 'h-8 pe-8 ps-8 text-[12px]', icon: 'start-2.5', chevron: 'end-2.5' },
      md: { input: 'h-9 pe-9 ps-9 text-[13px]', icon: 'start-3', chevron: 'end-3' },
    },
  },
  defaultVariants: { size: 'md' },
});

export type DatePickerVariantProps = VariantProps<typeof datePickerVariants>;

import { addDays, addMonths, endOfMonth, isSameDay, startOfDay, startOfMonth, type DateRange } from '../calendar/calendar-utils';

export interface DateRangePreset {
  id: string;
  label: string;
  /** Range relative to "today"; omit for the "Custom" entry, which hands focus to the calendar. */
  range?: (today: Date) => DateRange;
}

/** Today, Last 7 days, Last 30 days, This month (to date), Last month, Custom. */
export const DEFAULT_DATE_RANGE_PRESETS: DateRangePreset[] = [
  { id: 'today', label: 'Today', range: (t) => ({ start: startOfDay(t), end: startOfDay(t) }) },
  { id: 'last-7', label: 'Last 7 days', range: (t) => ({ start: addDays(t, -6), end: startOfDay(t) }) },
  { id: 'last-30', label: 'Last 30 days', range: (t) => ({ start: addDays(t, -29), end: startOfDay(t) }) },
  { id: 'this-month', label: 'This month', range: (t) => ({ start: startOfMonth(t), end: startOfDay(t) }) },
  {
    id: 'last-month',
    label: 'Last month',
    range: (t) => {
      const m = startOfMonth(addMonths(startOfMonth(t), -1));
      return { start: m, end: endOfMonth(m) };
    },
  },
  { id: 'custom', label: 'Custom' },
];

/** The preset whose range equals `value`, if any. */
export function matchPreset(presets: DateRangePreset[], value: DateRange, today: Date) {
  return presets.find((p) => {
    const r = p.range?.(today);
    return !!r && isSameDay(r.start, value.start) && isSameDay(r.end, value.end);
  });
}

export { DatePicker, type DatePickerProps } from './DatePicker';
export { DateRangePicker, DateRangeInput, type DateRangePickerProps, type DateRangeInputProps } from './DateRangePicker';
export { DEFAULT_DATE_RANGE_PRESETS, type DateRangePreset } from './date-range-presets';
export { datePickerVariants, type DatePickerVariantProps } from './date-picker.variants';
export { doc as datePickerDoc } from './DatePicker.doc';
